INSERT INTO artists (id, email, password_hash, stage_name, biography, avatar_url, cover_url, is_active, follower_count, created_at) VALUES
  ('c3524ab3-9531-5bf2-bb29-0f6b43c0225f', 'artist1@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Sơn Tùng M-TP', 'Sơn Tùng M-TP là ca sĩ, nhạc sĩ, nhà sản xuất âm nhạc hàng đầu Việt Nam.', 'https://cdn-images.dzcdn.net/images/artist/736c5b8ff5a001b724fb92c7471c9f1d/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/736c5b8ff5a001b724fb92c7471c9f1d/1000x1000-000000-80-0-0.jpg', true, 25693, NOW()),
  ('70b0eb7d-c1ab-57c1-ab9b-9996b6445d8b', 'artist2@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Hoàng Thùy Linh', 'Hoàng Thùy Linh là nữ ca sĩ nổi tiếng với phong cách âm nhạc dân gian đương đại độc đáo.', 'https://cdn-images.dzcdn.net/images/artist/ada412ca9a4796d6a7584567b871779a/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/ada412ca9a4796d6a7584567b871779a/1000x1000-000000-80-0-0.jpg', true, 9474, NOW()),
  ('c391cfa5-e128-59f9-8f87-ad6e18123bab', 'artist3@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Bích Phương', 'Bích Phương là nữ ca sĩ đa tài sở hữu hàng loạt bản hit đình đám trên thị trường V-Pop.', 'https://cdn-images.dzcdn.net/images/artist/c81fc5425d0279cc0b9c1d498ba3b457/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/c81fc5425d0279cc0b9c1d498ba3b457/1000x1000-000000-80-0-0.jpg', true, 4973, NOW()),
  ('114f2bce-4cb1-50a5-b79d-59e1e3366647', 'artist4@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Phan Mạnh Quỳnh', 'Phan Mạnh Quỳnh là nhạc sĩ, ca sĩ với những sáng tác tự sự, mộc mạc và giàu cảm xúc.', 'https://cdn-images.dzcdn.net/images/artist/273020e118c822eb6c3992d61db4020b/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/273020e118c822eb6c3992d61db4020b/1000x1000-000000-80-0-0.jpg', true, 1118, NOW()),
  ('8747fb8d-8dff-5c14-b930-d2c5a21787a3', 'artist5@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'HIEUTHUHAI', 'HIEUTHUHAI là nam rapper tài năng, gương mặt tiêu biểu của thế hệ rap hiện đại.', 'https://cdn-images.dzcdn.net/images/artist/731891d7627e78e25ea9e507d3fd8333/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/731891d7627e78e25ea9e507d3fd8333/1000x1000-000000-80-0-0.jpg', true, 1129, NOW()),
  ('e9579435-5a20-5676-af7a-ea0762795413', 'artist6@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Wren Evans', 'Wren Evans là nghệ sĩ trẻ Gen Z nổi bật với tư duy âm nhạc thời thượng và phá cách.', 'https://cdn-images.dzcdn.net/images/artist/ee2f42bb7a077ee88b189f4edf422b3e/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/ee2f42bb7a077ee88b189f4edf422b3e/1000x1000-000000-80-0-0.jpg', true, 1156, NOW()),
  ('7512a3c2-dab1-529e-ac2d-278e0e4f7d82', 'artist7@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'tlinh', 'tlinh là nữ rapper, ca sĩ cá tính với chất giọng lôi cuốn và phong cách âm nhạc hiện đại.', 'https://cdn-images.dzcdn.net/images/artist/395e24e799b806e4b42e5b913f949fdc/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/395e24e799b806e4b42e5b913f949fdc/1000x1000-000000-80-0-0.jpg', true, 2143, NOW()),
  ('c41afe64-d8e7-53dd-9f44-24dc6a05523a', 'artist8@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Mỹ Tâm', 'Mỹ Tâm là ''Họa mi tóc nâu'', biểu tượng âm nhạc Việt Nam với sự nghiệp đỉnh cao suốt hơn 2 thập kỷ.', 'https://cdn-images.dzcdn.net/images/artist/a53d47ab3b948026c53d9fc43958e61e/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/a53d47ab3b948026c53d9fc43958e61e/1000x1000-000000-80-0-0.jpg', true, 11336, NOW()),
  ('5d1ba707-575d-5905-89f2-80e81d22b1cf', 'artist9@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Tuấn Hưng', 'Tuấn Hưng là nam ca sĩ gạo cội gắn liền với nhiều bản tình ca bất hủ trong lòng người yêu nhạc.', 'https://cdn-images.dzcdn.net/images/artist/5b3d2f901ad311bf361452b0209312cc/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/5b3d2f901ad311bf361452b0209312cc/1000x1000-000000-80-0-0.jpg', true, 27, NOW()),
  ('f2a5fc37-c321-597a-b830-b888e28fc092', 'artist10@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Ưng Hoàng Phúc', 'Ưng Hoàng Phúc là nam thần tượng thanh xuân của hàng triệu khán giả Việt với gia tài bài hit đồ sộ.', 'https://cdn-images.dzcdn.net/images/artist/ce559b5c0647d209d5a6b5279c6f0bbe/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/ce559b5c0647d209d5a6b5279c6f0bbe/1000x1000-000000-80-0-0.jpg', true, 347, NOW()),
  ('d06a8152-dfda-5946-a6bf-4f20de22fce0', 'artist11@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Noo Phước Thịnh', 'Noo Phước Thịnh là nam ca sĩ tài năng sở hữu giọng hát nội lực và phong cách trình diễn ấn tượng.', 'https://cdn-images.dzcdn.net/images/artist/2fc00c376f14991589b28a740a147441/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/2fc00c376f14991589b28a740a147441/1000x1000-000000-80-0-0.jpg', true, 1767, NOW()),
  ('5f3fb892-e5b8-50d9-a6cf-49c4f5ea7f1a', 'artist12@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Lệ Quyên', 'Lệ Quyên được mệnh danh là ''Nữ hoàng phòng trà'' với giọng hát trữ tình da diết.', 'https://cdn-images.dzcdn.net/images/artist/440e64a551013775f634f3538f6e03a0/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/440e64a551013775f634f3538f6e03a0/1000x1000-000000-80-0-0.jpg', true, 2633, NOW()),
  ('81012232-2799-5f09-805e-c0a4cbb8ae85', 'artist13@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Đen', 'Đen Vâu là rapper giản dị, mộc mạc với những ca khúc giàu triết lý và sự đồng cảm.', 'https://cdn-images.dzcdn.net/images/artist/da485d4cbf15cccb0f94a720ce03f2c3/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/da485d4cbf15cccb0f94a720ce03f2c3/1000x1000-000000-80-0-0.jpg', true, 8139, NOW()),
  ('724873d1-a2d1-5477-bd55-3cdf8a0d3ad1', 'artist14@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Low G', 'Low G là rapper tài năng của giới underground nổi tiếng với phong cách nhả vần độc nhất vô nhị.', 'https://cdn-images.dzcdn.net/images/artist/8e41c01c6de212b06c8e952772a08ed9/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/8e41c01c6de212b06c8e952772a08ed9/1000x1000-000000-80-0-0.jpg', true, 579, NOW()),
  ('9da31e44-2c26-5a86-8956-6791e4875e06', 'artist15@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Vũ.', 'Vũ. được xem là ''Hoàng tử Indie Việt'' với những bản tình ca da diết, trầm buồn.', 'https://cdn-images.dzcdn.net/images/artist/3b39de9719ace79996aa2a893a1d42c7/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/3b39de9719ace79996aa2a893a1d42c7/1000x1000-000000-80-0-0.jpg', true, 1326, NOW()),
  ('8b2c057c-20cd-593d-b65f-15671a29e294', 'artist16@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'The Weeknd', 'The Weeknd is a Canadian singer, songwriter, and record producer known for his sonic versatility and dark lyricism.', 'https://cdn-images.dzcdn.net/images/artist/581693b4724a7fcfa754455101e13a44/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/581693b4724a7fcfa754455101e13a44/1000x1000-000000-80-0-0.jpg', true, 14762776, NOW()),
  ('42f8c8e2-ad35-5a3b-be03-2d4de004dddd', 'artist17@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Bruno Mars', 'Bruno Mars is an American singer-songwriter, producer, and showman known for his energetic performances and vintage flair.', 'https://cdn-images.dzcdn.net/images/artist/90f0b5b11df4f87ee878f38569b5995b/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/90f0b5b11df4f87ee878f38569b5995b/1000x1000-000000-80-0-0.jpg', true, 12840022, NOW()),
  ('e0354ca3-e334-5246-9422-4b2693a4044d', 'artist18@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Billie Eilish', 'Billie Eilish is an American singer and songwriter who first gained public attention with her breakout hit Ocean Eyes.', 'https://cdn-images.dzcdn.net/images/artist/8eab1a9a644889aabaca1e193e05f984/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/8eab1a9a644889aabaca1e193e05f984/1000x1000-000000-80-0-0.jpg', true, 9287475, NOW()),
  ('d841022f-3a46-5307-8f80-d68c62cefdf5', 'artist19@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Ed Sheeran', 'Ed Sheeran is an English singer-songwriter who has sold more than 150 million records worldwide.', 'https://cdn-images.dzcdn.net/images/artist/d6bb84390641d8ae9118228d9544e53d/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/d6bb84390641d8ae9118228d9544e53d/1000x1000-000000-80-0-0.jpg', true, 20947770, NOW()),
  ('cee9245e-bcf7-5e2d-b358-f58f444a6447', 'artist20@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Justin Bieber', 'Justin Bieber is a Canadian pop sensation recognized for his genre-melding musicianship and global impact.', 'https://cdn-images.dzcdn.net/images/artist/fe097f693cebf1f882e3da79e99e3bf9/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/fe097f693cebf1f882e3da79e99e3bf9/1000x1000-000000-80-0-0.jpg', true, 11177739, NOW()),
  ('7a33629f-f593-55d2-b73b-a41678b82a9a', 'artist21@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Ariana Grande', 'Ariana Grande is an American pop icon celebrated for her incredible vocal range and chart-topping albums.', 'https://cdn-images.dzcdn.net/images/artist/721d8fab84b315502de422b8d0901509/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/721d8fab84b315502de422b8d0901509/1000x1000-000000-80-0-0.jpg', true, 13455359, NOW()),
  ('9d6df35c-b67b-5b3f-b22e-50f13be27079', 'artist22@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Dua Lipa', 'Dua Lipa is an English and Albanian pop powerhouse known for her signature disco-pop and dance hits.', 'https://cdn-images.dzcdn.net/images/artist/877872aaf75694f11d53c318700ab2b5/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/877872aaf75694f11d53c318700ab2b5/1000x1000-000000-80-0-0.jpg', true, 8802188, NOW()),
  ('6f8c151f-9378-5bae-aeb0-3a191bc0c2de', 'artist23@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Drake', 'Drake is a world-renowned Canadian rapper and singer, one of the best-selling music artists of all time.', 'https://cdn-images.dzcdn.net/images/artist/eb0ed5b21d1ea5af021fc074ded0e91f/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/eb0ed5b21d1ea5af021fc074ded0e91f/1000x1000-000000-80-0-0.jpg', true, 24117869, NOW()),
  ('5952d0d4-70a0-53ec-a378-29b6ce7d024b', 'artist24@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Post Malone', 'Post Malone is an American singer-songwriter known for his introspective songwriting and distinct vocal style.', 'https://cdn-images.dzcdn.net/images/artist/a5a8cca44e7eab2db7d44e039bed2574/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/a5a8cca44e7eab2db7d44e039bed2574/1000x1000-000000-80-0-0.jpg', true, 4213918, NOW()),
  ('21df0fc3-b261-5838-8f03-b3801b5086d9', 'artist25@mcmusic.com', '$2a$10$wF5/pTEqIFbhMyaiEo5noOnEqQqOBRYZULZBD.v35TwZNtbwyadJa', 'Charlie Puth', 'Charlie Puth is an American singer and record producer famous for his pitch-perfect melodies and global pop anthems.', 'https://cdn-images.dzcdn.net/images/artist/c355b366638e0c5f20f4b265f0f12646/500x500-000000-80-0-0.jpg', 'https://cdn-images.dzcdn.net/images/artist/c355b366638e0c5f20f4b265f0f12646/1000x1000-000000-80-0-0.jpg', true, 2310012, NOW()),
